"""로직 결과를 보존하는 보고서 출력. 외부 의존성/API 없음."""
import math

FEATURES = (
    ("Amplitude of pelvis oscillation", "Amplitude of pelvis oscillation 골반 진동 진폭"),
    ("Elbow angle", "elbow angle 팔꿈치 각도"),
    ("Trunk flexion angle", "Trunk flexion angle 몸통기울기"),
    ("Postural lean angle", "Postural lean angle 전방자세기울기"),
)

def finite(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def value_text(key, result):
    value = result.get("value")
    if key == "Elbow angle":
        values = [v for v in value if finite(v)] if isinstance(value, list) else []
        if not values:
            return "미측정"
        return f"평균 {sum(values)/len(values):.2f}° (최소 {min(values):.2f}°–최대 {max(values):.2f}°)"
    if not finite(value):
        return "미측정"
    if key == "Amplitude of pelvis oscillation":
        return f"{value:.4f} (신장 대비 {value*100:.2f}%)"
    return f"{value:.2f}°"



