def friendly_text(text):
    """Replace reviewed wording only; unknown text is preserved verbatim."""
    return DISPLAY_WORDING.get(text, text)


def json_value(value):
    """Represent unavailable/non-finite measurements as JSON null."""
    if isinstance(value, list):
        return [json_value(item) for item in value]
    return value if finite(value) else None


def render_report(features, summary, videos=None):
    """Build the public JSON report without changing feature decisions."""
    items = []
    for index, (key, label) in enumerate(FEATURES, start=1):
        result = features.get(key) or {}
        item = {
            "feature_id": f"feature{index}",
            "name": key,
            "label": label,
            "value": json_value(result.get("value")),
            "unit": "ratio" if index == 1 else "degree",
            "display_value": value_text(key, result),
            "outcome": friendly_text(result.get("outcome", "판정 결과 없음")),
            "instruction": friendly_text(result.get("instruction", "교정 방안 없음")),
        }
        if key == "Postural lean angle":
            item["knowledge"] = "대사비용: 활동을 수행하기 위해 신체가 소비하는 대사 에너지의 양"
        items.append(item)
    selected_videos = []
    for video in videos or []:
        url = video["url"]
        if not url.startswith(("https://", "http://")):
            raise ValueError("영상 주소는 http(s) URL이어야 합니다.")
        selected_videos.append({"title": video["title"], "url": url})
    return {
        "features": items,
        "summary": " ".join(summary.splitlines()).strip(),
        "exercise_videos": selected_videos,
    }
